// 84b2793c73399933355b2f8ee175d16aed3558eb
import { test, expect } from '@playwright/test';
test('administración sustituye un único rol sin selección múltiple', async ({
  page
}) => {
  await page.goto('/login');
  await page.getByLabel('Correo electrónico').fill('admin@aaud.gob.pa');
  await page.locator('#login-password').fill(process.env.E2E_PASSWORD || 'e2e-test-password');
  await page.getByRole('button', {
    name: 'Ingresar'
  }).click();
  await page.waitForURL('**/paz-salvos/consultar');
  await page.goto('/admin/users');
  await page.getByRole('button', {
    name: 'Nuevo usuario',
    exact: true
  }).click();
  const dialog = page.getByRole('dialog');
  await expect(dialog.getByRole('switch', {
    name: 'Vincular con AAUD OAUTH'
  })).toHaveAttribute('aria-checked', 'true');
  await expect(dialog.getByRole('button', {
    name: 'Crear usuario',
    exact: true
  })).toBeDisabled();
  await dialog.getByLabel('Buscar usuario en Active Directory').fill('single-role');
  await dialog.getByLabel('Buscar usuario en Active Directory').press('Enter');
  const candidate = dialog.locator('.sso-candidate');
  await expect(candidate).toHaveCount(1);
  await candidate.click();
  const email = await page.locator('#create-email').inputValue();
  await expect(page.locator('#create-name')).toHaveValue('Single Role E2E');
  await expect(page.locator('#create-email')).toHaveAttribute('readonly');
  await expect(page.locator('#create-username')).toHaveAttribute('readonly');
  const agency = await page.locator('#create-agency option').nth(1).getAttribute('value');
  await page.locator('#create-agency').selectOption(agency);
  await expect(page.locator('#create-role')).not.toHaveAttribute('multiple');
  await page.locator('#create-role').selectOption('operador');
  const create = dialog.getByRole('button', {
    name: 'Crear usuario y vincular SSO',
    exact: true
  });
  await expect(create).toBeEnabled();
  await create.click();
  await expect(dialog).toHaveCount(0);
  const row = page.locator('tr').filter({
    hasText: email
  });
  await expect(row.locator('.role-badge')).toHaveText('operador');
  await expect(row.locator('.sso-badge')).toHaveText('SSO: SI');
  await row.getByRole('button', {
    name: 'Editar usuario',
    exact: true
  }).click();
  await expect(page.locator('#edit-role')).not.toHaveAttribute('multiple');
  await page.locator('#edit-role').selectOption('consulta');
  await page.getByRole('dialog').getByRole('button', {
    name: 'Guardar cambios',
    exact: true
  }).click();
  await expect(row.locator('.role-badge')).toHaveCount(1);
  await expect(row.locator('.role-badge')).toHaveText('consulta');
  await expect(row.locator('.sso-badge')).toHaveText('SSO: SI');
});
